import math


def parse_amount(text):
    """Parse a monetary amount string into a non-negative finite float.

    Accepts decimal points or commas as the decimal separator and ignores
    surrounding whitespace. Zero is allowed.

    Raises ValueError for empty input, negative values and non-finite
    values (nan, inf, -inf).
    """
    if not isinstance(text, str):
        text = str(text)
    text = text.strip()
    if not text:
        raise ValueError("empty amount")
    if ',' in text or '.' in text:
        separators = sum(',' in text, '.' in text)
        if separators != 1:
            raise ValueError("ambiguous decimal separator")
        text = text.replace(',', '.')
    try:
        value = float(text)
    except ValueError:
        raise ValueError("invalid amount: %r" % text)
    if value < 0 or not math.isfinite(value):
        raise ValueError("negative or non-finite amount: %r" % text)
    return value

import math


def parse_amount(text):
    """Parse a monetary amount string into a non-negative finite float.

    Accepts decimal points or commas as the decimal separator and ignores
    surrounding whitespace. Zero is allowed.

    Raises ValueError for empty input, negative values and non-finite
    values (nan, inf, -inf).
    """
    if not isinstance(text, str):
        text = str(text)
    text = text.strip()
    if not text:
        raise ValueError("empty amount")
    if ',' in text or '.' in text:
        if sum(c in text for c in (',', '.')) != 1:
            raise ValueError("ambiguous decimal separator")
        text = text.replace(',', '.')
    try:
        value = float(text)
    except ValueError:
        raise ValueError("invalid amount: %r" % text)
    if value < 0 or not math.isfinite(value):
        raise ValueError("negative or non-finite amount: %r" % text)
    return value
